// Rotación gradual de un enemigo hacia el jugador
public class EnemyAim : MonoBehaviour
{
    public Transform jugador;
    public float velocidadRotacion = 2f;

    void Update()
    {
        // Calcular la rotación objetivo mirando al jugador
        Vector3 dir = jugador.position - transform.position;
        Quaternion rotObjetivo = Quaternion.LookRotation(dir);

        // Slerp: rotación suave por esfera (no distorsiona)
        transform.rotation = Quaternion.Slerp(
            transform.rotation,
            rotObjetivo,
            velocidadRotacion * Time.deltaTime
        );
    }
}

