IEnumerator FadeOut()
{
    float t = 0f;
    while (t < 1f)
    {
        t += Time.deltaTime / duracion;
        audioSource.volume = Mathf.Lerp(1f, 0f, t);
        yield return null;
    }
    audioSource.volume = 0f;
}

